// Generated by the build next to the game image: the build's sound-driver ranges (melee_game.snapexcl).
extern "C" const uint8_t mu_embedded_snapexcl[], mu_embedded_snapexcl_end[];

namespace net_host {
namespace {
using Clock = std::chrono::steady_clock;
double ms_since(Clock::time_point start) { return std::chrono::duration<double, std::milli>(Clock::now() - start).count(); }
Options options;
Log say = nullptr;
std::string confirmed_rows_source;      // every row given to on_retrace, in order

void report_series(const char* label, std::vector<float> values) {
  if (values.empty()) { say("%s: none", label); return; }
  double sum = 0; for (float v : values) sum += v;
  std::sort(values.begin(), values.end());
  say("%s: %zu, avg %.3f ms, median %.3f, p99 %.3f, worst %.3f", label, values.size(), sum / values.size(), values[values.size() / 2],
      values[size_t(values.size() * 0.99)], values.back());
}
bool write_file(const std::string& path, const void* data, size_t size) {
  FILE* out = std::fopen(path.c_str(), "wb");
  if (!out) return false;
  const bool ok = std::fwrite(data, 1, size, out) == size;
  return std::fclose(out) == 0 && ok;
}

struct NetRun {
  bool on = false, asked = false;
  int index = 0;
  uint8_t character = 2;
  int32_t latest_saved = INT32_MIN;
  uint64_t saves = 0, loads = 0, missing = 0, selftests = 0, selftest_failures = 0, selftest_bytes = 0;
  uint64_t depth_count[16]{};
  std::vector<float> save_ms, restore_ms;
  bool failed = false;
  int mode = 2;                     // Slippi mode of the requested match
  std::string code = "PEER#001";    // the opponent's connect code (Direct)
  bool ranked_refused = false;
  int attempts = 1;                 // --net-retry: how often the match has been asked for
  bool connected_once = false, gave_up = false;
  Clock::time_point started, last_request;
  // Rows of the digest (offset, length) and whether the state they show was later replaced by a
  // rollback: a frame simulated on a predicted input is shown once and corrected without being shown again.
  std::vector<std::pair<uint32_t, uint32_t>> rows;
  std::vector<uint8_t> superseded;
  // Timing of online frames (work only: the host's pacing sleep is taken out).
  bool in_resim = false;
  Clock::time_point last_command;
  uint64_t loads_at_last_frame = 0, slept_at_last_frame = 0;
  std::vector<float> first_pass_ms, rollback_frame_ms, repeated_ms;
  // What happened inside each first-pass frame, to explain the slow ones.
  struct FrameCost { float work_ms, log_ms, command_ms; uint32_t retrace, log_lines, faults, disc_reads, row; };
  std::vector<FrameCost> first_pass_cost;
  uint64_t log_ns = 0, log_lines = 0, command_ns = 0;            // running totals
  pthread_t sim_thread{}; bool have_sim_thread = false;
  std::atomic<uint64_t> other_log_ns{0}, other_log_lines{0};
  uint64_t log_ns_last = 0, log_lines_last = 0, command_ns_last = 0, faults_last = 0, disc_last = 0;
  // The game's own per-frame state checksum (what Slippi's desync detection compares), last value
  // per online frame: after a rollback the frame is simulated again and the value is replaced, so
  // these are final states and two machines can be compared by them.
  bool check = true;
  std::map<int32_t, std::pair<uint32_t, uint32_t>> state_sum;     // frame -> checksum, RNG seed
  uint32_t desync_lines = 0;
} net;

uint32_t net_be32(const uint8_t* p) { return uint32_t(p[0]) << 24 | uint32_t(p[1]) << 16 | uint32_t(p[2]) << 8 | p[3]; }
void net_put32(std::vector<uint8_t>* out, uint32_t v) { out->push_back(uint8_t(v >> 24)); out->push_back(uint8_t(v >> 16)); out->push_back(uint8_t(v >> 8)); out->push_back(uint8_t(v)); }
// --net-store engine: melee-unlocked's own snapshot engine instead of the hot-page store, to tell
// what is a property of the engine's rollback from what is a property of our store.
native_savestate::Engine net_engine;
bool net_tracking() {
  if (options.engine_store) {
    if (!net_engine.active()) { net_engine.begin(snapshot_spans(options.embedded_image), 12); say("net: melee-unlocked's snapshot engine covers %zu bytes in %zu spans", net_engine.bytes(), net_engine.spans().size()); }
    return true;
  }
  if (mu_rollback::active()) return true;
  if (net.failed) return false;
  std::string error;
  if (!mu_rollback::begin(snapshot_spans(options.embedded_image), 12, false, &error)) { net.failed = true; say("net: cannot start the snapshot store: %s", error.c_str()); return false; }
  say("net: snapshot store tracking %zu pages (%.1f MiB)", mu_rollback::tracked_pages(), mu_rollback::tracked_pages() / 256.0);
  return true;
}
// The game's slippi_command. Savestates (0xB1 capture, 0xB2 load, both keyed by frame) and the
// self-test (0xF0 keep a reference, 0xF1 compare with it) are served by the hot-page store; every
// other command goes to the app's Slippi device.
int32_t net_slippi_command(uint8_t command, const uint8_t* payload, uint32_t size, uint8_t* response, uint32_t capacity, uint32_t* response_size) {
  if (response_size) *response_size = 0;
  std::vector<uint8_t> reply;
  if ((command == 0xB1 || command == 0xB2) && payload && size >= 4) {
    const int32_t frame = int32_t(net_be32(payload));
    if (!net_tracking()) return -1;
    const auto t = Clock::now();
    const bool engine = options.engine_store;
    // While the game simulates frames again, each one saves its state first: the time from the
    // previous save (or the load) to this one is one repeated frame.
    if (command == 0xB1 && net.in_resim) net.repeated_ms.push_back(float(std::chrono::duration<double, std::milli>(t - net.last_command).count()));
    if (command == 0xB1) {
      if (engine) net_engine.capture(frame); else mu_rollback::save(frame);
      net.save_ms.push_back(float(ms_since(t))); ++net.saves;
      net.latest_saved = std::max(net.latest_saved, frame);
    } else if (engine ? net_engine.load_keep(frame) : mu_rollback::restore(frame)) {
      net.restore_ms.push_back(float(ms_since(t))); ++net.loads;
      const int depth = net.latest_saved - frame + 1;        // frames simulated again, including the newest
      ++net.depth_count[std::min(std::max(depth, 0), 15)];
      for (int i = 0; i <= depth && size_t(i) < net.superseded.size(); ++i) net.superseded[net.superseded.size() - 1 - size_t(i)] = 1;
      net.latest_saved = frame;
    } else { ++net.missing; say("net: no snapshot kept for frame %d", frame); }
    net.last_command = Clock::now();
    return 0;
  }
  // Ranked is refused exactly where melee-unlocked refuses it: the search does not start, and the
  // match state the game polls next says so. (Its host has no Ranked backend either.)
  if (command == 0xB4 && payload && size >= 1) net.ranked_refused = payload[0] == 0;
  if (command == 0xB4 && net.ranked_refused) { say("net: %s", netplay_bridge::ranked_refusal()); return 0; }
  if (command == 0xBA) net.ranked_refused = false;            // CMD_CLEANUP_CONNECTION
  if (command == 0xF0 && payload && size == 4) {
    if (net_tracking()) { if (options.engine_store) net_engine.keep_reference(int32_t(net_be32(payload))); else mu_rollback::remember(); }
    return 0;
  }
  if (command == 0xF1 && payload && size == 4) {
    ++net.selftests;
    const auto diffs = options.engine_store ? net_engine.compare_reference() : mu_rollback::differences_from_remembered(100000);
    reply.assign(4, 0);
    if (!diffs.empty()) {
      ++net.selftest_failures;
      const size_t listed = std::min<size_t>(diffs.size(), 480);
      reply.clear(); net_put32(&reply, uint32_t(listed));
      size_t bytes = 0;
      for (size_t i = 0; i < diffs.size(); ++i) { if (i < listed) { net_put32(&reply, uint32_t(diffs[i].first)); net_put32(&reply, diffs[i].second); } bytes += diffs[i].second; }
      net.selftest_bytes += bytes;
      if (net.selftest_failures <= 5) say("net selftest: frame %d differs after re-simulation: %zu ranges, %zu bytes", int32_t(net_be32(payload)), diffs.size(), bytes);
    }
  } else {
    const auto t = Clock::now();
    const bool handled = netplay_bridge::handle(command, payload, size, &reply);
    net.command_ns += uint64_t(std::chrono::duration_cast<std::chrono::nanoseconds>(Clock::now() - t).count());
    if (!handled) return -1;
  }
  // --net-retry: a direct peer that is not there yet. One attempt of the netplay client lasts 8 s; when it
  // ends without a connection the match is asked for again, and the game keeps seeing "connecting"
  // instead of the error, until the peer answers or the time is up. Whichever side starts first
  // simply keeps trying; a connect that arrives between two attempts is repeated by its sender and
  // lands in the next one.
  if (command == 0xB3 && !reply.empty() && !net.connected_once) {
    if (reply[0] == 4) {
      net.connected_once = true;
      say("net: connected on attempt %d, %.1f s after start", net.attempts, ms_since(net.started) / 1000);
    } else if (reply[0] == 5 && options.online.empty() && !net.ranked_refused) {
      const double elapsed = ms_since(net.started) / 1000;
      if (options.retry_seconds && ms_since(net.last_request) < 2000) {
        reply[0] = 3;       // the new attempt has only just been asked for: the old error is still on show
        if (reply.size() > 357 + 241) std::memset(reply.data() + 357, 0, 241);
      } else if (elapsed < options.retry_seconds) {
        say("net: attempt %d did not connect (%.1f s after start); trying again, up to %d s", net.attempts, elapsed, options.retry_seconds);
        std::vector<uint8_t> ignored;
        netplay_bridge::handle(0xBA, nullptr, 0, &ignored);          // CMD_CLEANUP_CONNECTION: drop the failed attempt
        netplay_bridge::request_match(net.mode, net.code, net.character, 0);
        ++net.attempts; net.last_request = Clock::now();
        reply[0] = 3;                                                 // still connecting, as far as the game is concerned
        if (reply.size() > 357 + 241) std::memset(reply.data() + 357, 0, 241);
      } else if (!net.gave_up) {
        net.gave_up = true;
        say("net: attempt %d did not connect (%.1f s after start); giving up%s", net.attempts, elapsed,
            options.retry_seconds ? "" : " (--net-retry SECONDS keeps trying)");
      }
    }
  }
  if (command == 0xB3 && net.ranked_refused && reply.size() > 357 + 64) {
    reply[0] = 5;                                             // MM_ERROR_ENCOUNTERED
    std::memset(reply.data() + 357, 0, 241);                  // the error text field of the match state reply
    std::snprintf(reinterpret_cast<char*>(reply.data()) + 357, 241, "%s", netplay_bridge::ranked_refusal());
  }
  if (reply.size() > capacity || (!reply.empty() && !response)) return -2;
  if (!reply.empty()) std::memcpy(response, reply.data(), reply.size());
  if (response_size) *response_size = uint32_t(reply.size());
  return 0;
}
// The game asks at boot whether to enter an online match without menus; the first time, the match is requested.
int32_t net_online_test_match(MuOnlineMatch* out) {
  if (!net.asked) {
    net.asked = true; net.started = net.last_request = Clock::now();
    const bool asked = netplay_bridge::request_match(net.mode, net.code, net.character, 0);
    net.ranked_refused = !asked;
    say("net: %s (mode %d, character %u)", asked ? "asked for a match" : netplay_bridge::ranked_refusal(), net.mode, net.character);
  }
  if (out) { std::memset(out, 0, sizeof *out); out->mode = uint8_t(net.mode); out->local_port = 0; }
  return 1;      // 1 = the diagnostic harness (generated inputs and the self-test are allowed)
}
uint32_t net_retrace_count() { return linux_host::counters().retraces; }
void (*net_resim_original)(int32_t) = nullptr;
void net_resim_phase(int32_t entering) {
  net.in_resim = entering != 0;
  if (net_resim_original) net_resim_original(entering);
}
// The game's log lines pass through here. With MELEE_TRACE_P2P_PADS the game writes one "state f"
// line per simulated frame (and one "pads f" line): those are collected, not printed.
void (*net_log_original)(const char*) = nullptr;
void net_log(const char* text) {
  if (text && !std::strncmp(text, "state f ", 8)) {
    int frame = 0; unsigned sum = 0, seed = 0;
    if (std::sscanf(text, "state f %d sum %x seed %x", &frame, &sum, &seed) == 3) net.state_sum[frame] = {sum, seed};
    return;
  }
  if (text && !std::strncmp(text, "pads f ", 7)) return;
  if (text && (std::strstr(text, "DESYNC") || std::strstr(text, "desync risk"))) ++net.desync_lines;
  LogTime timed;
  if (net_log_original) net_log_original(text);
}
// The slowest first-pass frames and what was inside them.
void report_slow_frames() {
  auto& all = net.first_pass_cost;
  if (all.empty()) return;
  size_t over8 = 0, with_log = 0, with_disc = 0, with_faults = 0, with_command = 0, unexplained = 0;
  for (const auto& f : all) {
    if (f.work_ms < 8) continue;
    ++over8;
    const bool log = f.log_ms >= 1, disc = f.disc_reads != 0, faults = f.faults >= 50, command = f.command_ms >= 1;
    with_log += log; with_disc += disc; with_faults += faults; with_command += command; unexplained += !(log || disc || faults || command);
  }
  say("net: first-pass frames of 8 ms or more: %zu of %zu; with 1 ms or more of log writing %zu, with a disc read %zu, with 50 or more write faults %zu, "
      "with 1 ms or more inside the netplay device %zu, none of these %zu", over8, all.size(), with_log, with_disc, with_faults, with_command, unexplained);
  std::vector<float> log_ms, command_ms;
  for (const auto& f : all) { log_ms.push_back(f.log_ms); command_ms.push_back(f.command_ms); }
  report_series("net: log writing inside a first-pass frame", log_ms);
  report_series("net: netplay device (sockets, input exchange) inside a first-pass frame", command_ms);
  say("net: log lines written by the netplay client's own threads (outside the frame): %llu, %.1f ms in all",
      (unsigned long long)net.other_log_lines.load(), net.other_log_ns.load() / 1e6);
  std::vector<size_t> order(all.size());
  for (size_t i = 0; i < order.size(); ++i) order[i] = i;
  const size_t top = std::min<size_t>(12, order.size());
  std::partial_sort(order.begin(), order.begin() + top, order.end(), [&](size_t a, size_t b) { return all[a].work_ms > all[b].work_ms; });
  for (size_t i = 0; i < top; ++i) {
    const auto& f = all[order[i]];
    unsigned match_frame = 0;
    if (f.row < net.rows.size()) std::sscanf(confirmed_rows_source.c_str() + net.rows[f.row].first, "%*u,%*u,%*u,%u", &match_frame);
    say("net: slow frame %zu: %.3f ms at retrace %u (match frame %u, %zu frames into the match): log %.3f ms in %u lines, netplay device %.3f ms, "
        "%u write faults, %u disc reads", i + 1, f.work_ms, f.retrace, match_frame, order[i], f.log_ms, f.log_lines, f.command_ms, f.faults, f.disc_reads);
  }
}
} // namespace

void report() {
  if (!net.on) return;
  say("net: %llu state saves, %llu rollbacks (loads), %llu loads with no snapshot; app device counted %llu rollbacks", (unsigned long long)net.saves,
      (unsigned long long)net.loads, (unsigned long long)net.missing, (unsigned long long)netplay_bridge::rollbacks_seen_by_device());
  std::string depths; char part[32];
  for (int d = 0; d < 16; ++d) if (net.depth_count[d]) { std::snprintf(part, sizeof part, " %d%s:%llu", d, d == 15 ? "+" : "", (unsigned long long)net.depth_count[d]); depths += part; }
  say("net: rollback depth (frames simulated again : how often):%s", depths.empty() ? " none" : depths.c_str());
  report_series("net: save", net.save_ms);
  report_series("net: restore", net.restore_ms);
  report_series("net: online frame without a rollback (work only)", net.first_pass_ms);
  report_slow_frames();
  report_series("net: online frame with a rollback (load, repeated frames, the new frame, saves)", net.rollback_frame_ms);
  report_series("net: one repeated frame inside a rollback (with its save)", net.repeated_ms);
  {
    size_t late = 0; for (float v : net.rollback_frame_ms) if (v > 1000.0f / 60) ++late;
    say("net: rollback frames over 16.67 ms: %zu of %zu", late, net.rollback_frame_ms.size());
  }
  // Final states, to compare two machines by eye: a running hash of (frame, state checksum, RNG seed)
  // over all frames up to each checkpoint. The last frames of a run may still be predictions and are left out.
  if (net.check && !net.state_sum.empty()) {
    const int32_t first = net.state_sum.begin()->first, last = net.state_sum.rbegin()->first - 30;
    uint64_t h = 0xcbf29ce484222325ull; size_t n = 0; std::string line;
    auto mix = [&](uint32_t v) { for (int i = 0; i < 4; ++i) { h ^= (v >> (8 * i)) & 0xff; h *= 0x100000001b3ull; } };
    for (const auto& entry : net.state_sum) {
      if (entry.first > last) break;
      mix(uint32_t(entry.first)); mix(entry.second.first); mix(entry.second.second); ++n;
      if (entry.first > 0 && entry.first % 300 == 0) {
        char part[64]; std::snprintf(part, sizeof part, " %d:%08x", entry.first, uint32_t(h ^ (h >> 32)));
        line += part;
        if (line.size() > 150) { say("net check (frame:hash of all final states so far):%s", line.c_str()); line.clear(); }
      }
    }
    if (!line.empty()) say("net check (frame:hash of all final states so far):%s", line.c_str());
    say("net check: %zu frames from %d; %u desync messages from the game%s", n, first, net.desync_lines,
        net.desync_lines ? "" : " (the game's own checksum comparison with the other side found nothing)");
  }
  // The rows whose state was final when shown: these must be the same on both sides.
  std::string confirmed; size_t kept = 0;
  for (size_t i = 0; i < net.rows.size(); ++i) if (!net.superseded[i]) { confirmed.append(confirmed_rows_source, net.rows[i].first, net.rows[i].second); ++kept; }
  const std::string path = options.out_dir + "/digest-net-confirmed.csv";
  say("net: %zu of %zu shown states were never replaced by a rollback; %s %s", kept, net.rows.size(),
      write_file(path, confirmed.data(), confirmed.size()) ? "written to" : "COULD NOT WRITE", path.c_str());
  if (!options.selftest.empty())
    say("net selftest: %llu comparisons, %llu with differences (%llu bytes in all)%s", (unsigned long long)net.selftests, (unsigned long long)net.selftest_failures,
        (unsigned long long)net.selftest_bytes, net.selftests && !net.selftest_failures ? ": the engine's rollback is byte-exact with this store" : "");
}

std::vector<native_savestate::Span> snapshot_spans(bool embedded_image) {
  const auto& game = linux_host::game_api();
  std::vector<MuStateRegion> ranges(game.snapshot_ranges(nullptr, 0));
  ranges.resize(game.snapshot_ranges(ranges.data(), uint32_t(ranges.size())));
  std::vector<MuStateRegion> exclusions(game.state_exclusions(nullptr, 0));
  exclusions.resize(game.state_exclusions(exclusions.data(), uint32_t(exclusions.size())));
  // The sound driver's own state, listed by the game's build next to the image (melee_game.snapexcl:
  // "offset size ..." lines, offsets from the image base). The engine's host leaves it out of every
  // rollback snapshot, as a console savestate does.
  if (embedded_image) {
    const std::string text(reinterpret_cast<const char*>(mu_embedded_snapexcl), size_t(mu_embedded_snapexcl_end - mu_embedded_snapexcl));
    for (size_t at = 0; at < text.size();) {
      const size_t end = std::min(text.find('\n', at), text.size());
      unsigned long long offset = 0, size = 0;
      if (text[at] != '#' && std::sscanf(text.substr(at, end - at).c_str(), "%llx %llx", &offset, &size) == 2 && size)
        exclusions.push_back(MuStateRegion{reinterpret_cast<void*>(uintptr_t(linux_host::game_image_base + offset)), uint32_t(size)});
      at = end + 1;
    }
  }
  return native_savestate::subtract(ranges, exclusions);
}

bool parse_option(const std::string& arg, const std::function<std::string()>& next, Options* o) {
  if (arg == "--net") o->net = next();
  else if (arg == "--online") o->online = next();
  else if (arg == "--user-dir") o->user_dir = next();
  else if (arg == "--fake-user") o->fake_user = true;
  else if (arg == "--net-retry") o->retry_seconds = int(std::strtol(next().c_str(), nullptr, 0));
  else if (arg == "--net-delay") o->delay = int(std::strtol(next().c_str(), nullptr, 0));
  else if (arg == "--net-character") o->character = int(std::strtol(next().c_str(), nullptr, 0));
  else if (arg == "--net-inputs") o->inputs = uint32_t(std::strtoul(next().c_str(), nullptr, 0));
  else if (arg == "--selftest") o->selftest = next();
  else if (arg == "--net-store") o->engine_store = next() == "engine";
  else if (arg == "--net-no-check") o->no_check = true;
  else if (arg == "--track-remap") dirtytrack_set_method(DIRTYTRACK_REMAP);   // Horizon: the other way to make pages read-only (dirtytrack.h)
  else return false;
  return true;
}
void usage(Log log) {
  log("          [--net INDEX:LOCAL_PORT:REMOTE_IP:REMOTE_PORT] [--net-retry SECONDS] [--net-delay FRAMES] [--net-inputs SEED] [--selftest EVERY:DEPTH] [--track-remap]");
  log("          [--online unranked|direct:CODE|teams|party] [--user-dir DIR]   (builds with MU_NET_SERVICES=1 only)");
}
bool wanted(const Options& o) { return !o.net.empty() || !o.online.empty(); }
bool active() { return net.on; }

int start(const Options& given, Log log) {
  options = given; say = log;
  netplay_bridge::Setup setup;
  setup.delay_frames = options.delay; setup.retrace_count = net_retrace_count; setup.log_time = [](uint64_t ns) {
    if (net.have_sim_thread && pthread_equal(pthread_self(), net.sim_thread)) add_log_time(ns, true);
    else { net.other_log_ns += ns; ++net.other_log_lines; }       // the netplay client's own threads: not inside a frame
  };
  std::string error;
  if (!options.online.empty()) {
    // The app's real matchmaking, user file and reporting. Never started by a test on a development machine
    // except against a local mock (the Linux services build is pinned to it).
    const size_t colon = options.online.find(':');
    const std::string mode = options.online.substr(0, colon);
    net.mode = mode == "unranked" ? 1 : mode == "direct" ? 2 : mode == "teams" ? 3 : mode == "party" ? 4 : mode == "ranked" ? 0 : -1;
    net.code = colon == std::string::npos ? "" : options.online.substr(colon + 1);
    if (net.mode < 0) { say("--online wants unranked, direct:CODE, teams or party"); return 2; }
    setup.services = true; setup.fake_user = options.fake_user; setup.iso_path = options.iso_path;
    setup.local_index = int(options.inputs);        // only names the made-up user of a mock test
#ifdef __SWITCH__
    setup.user_dir = options.user_dir.empty() ? "sdmc:/switch/melee-nx-netplay/User" : options.user_dir;
#else
    setup.user_dir = options.user_dir.empty() ? options.out_dir + "/user" : options.user_dir;
#endif
    if (!netplay_bridge::start(setup, &error)) { say("online: %s", error.empty() ? "the online module did not start" : error.c_str()); return 1; }
    net.on = true;
    net.character = uint8_t(options.character >= 0 ? options.character : 2);
    if (options.inputs) { char seed[16]; std::snprintf(seed, sizeof seed, "%u", options.inputs); setenv("MELEE_ONLINE_TEST_INPUTS", seed, 1); }
    say("online: services on, mode %s%s%s, user folder %s, input delay %d", mode.c_str(), net.code.empty() ? "" : " with ", net.code.c_str(),
        setup.user_dir.c_str(), options.delay);
  } else {
    char ip[64] = {}; unsigned index = 0, local_port = 0, remote_port = 0;
    if (std::sscanf(options.net.c_str(), "%u:%u:%63[^:]:%u", &index, &local_port, ip, &remote_port) != 4 || index > 1) { say("--net wants INDEX:LOCAL_PORT:REMOTE_IP:REMOTE_PORT"); return 2; }
    setup.local_index = int(index); setup.local_port = uint16_t(local_port); setup.remote_ip = ip; setup.remote_port = uint16_t(remote_port);
    setup.user_dir = options.out_dir + "/user";
    if (!netplay_bridge::start(setup, &error)) { say("net: %s", error.c_str()); return 1; }
    net.on = true; net.index = int(index);
#ifndef __SWITCH__
    dirtytrack_install(nullptr);        // on Linux this also reports the address of any crash
#endif
    net.character = uint8_t(options.character >= 0 ? options.character : index ? 9 : 2);
    char seed[16]; std::snprintf(seed, sizeof seed, "%u", options.inputs ? options.inputs : index + 1);
    setenv("MELEE_ONLINE_TEST_INPUTS", seed, 1);
    say("net: player %u, listening on %u, peer at %s:%u, input delay %d, generated inputs seed %s%s%s", index, local_port, ip, remote_port,
        options.delay, seed, options.selftest.empty() ? "" : ", self-test ", options.selftest.c_str());
  }
  if (!options.selftest.empty()) setenv("MELEE_ONLINE_SELFTEST", options.selftest.c_str(), 1);
  net.check = !options.no_check;
  if (net.check) setenv("MELEE_TRACE_P2P_PADS", "1", 1);     // the per-frame state checksums (collected by net_log)
  return 0;
}

void install(MuHostApi* host) {
  if (!host || !net.on) return;
  host->slippi_command = net_slippi_command; host->online_test_match = net_online_test_match;
  // An online match is recorded as a replay; a host that keeps none must still take the calls.
  if (!host->replay_event) host->replay_event = [](uint8_t, const uint8_t*, uint32_t) {};
  if (!host->replay_finished) host->replay_finished = []() {};
  net_resim_original = host->resim_phase; host->resim_phase = net_resim_phase;
  net_log_original = host->log; host->log = net_log;
}

void on_retrace(const char* row, size_t length, bool fighting, double frame_ms) {
  if (!net.on) return;
  net.rows.push_back({uint32_t(confirmed_rows_source.size()), uint32_t(length)}); net.superseded.push_back(0);
  confirmed_rows_source.append(row, length);
  const uint64_t slept = linux_host::slept_nanoseconds();
  if (!net.have_sim_thread) { net.sim_thread = pthread_self(); net.have_sim_thread = true; }
  const uint64_t faults = dirtytrack_faults(), disc = linux_host::counters().disc_reads;
  if (frame_ms >= 0 && fighting) {
    const double work = frame_ms - double(slept - net.slept_at_last_frame) / 1e6;
    (net.loads != net.loads_at_last_frame ? net.rollback_frame_ms : net.first_pass_ms).push_back(float(work));
    if (net.loads == net.loads_at_last_frame)
      net.first_pass_cost.push_back({float(work), float((net.log_ns - net.log_ns_last) / 1e6), float((net.command_ns - net.command_ns_last) / 1e6),
                                     linux_host::counters().retraces, uint32_t(net.log_lines - net.log_lines_last), uint32_t(faults - net.faults_last),
                                     uint32_t(disc - net.disc_last), uint32_t(net.rows.size() - 1)});
  }
  net.loads_at_last_frame = net.loads; net.slept_at_last_frame = slept;
  net.log_ns_last = net.log_ns; net.log_lines_last = net.log_lines; net.command_ns_last = net.command_ns; net.faults_last = faults; net.disc_last = disc;
}

namespace { thread_local int log_depth = 0; }
void add_log_time(uint64_t nanoseconds, bool outermost) { if (outermost) { net.log_ns += nanoseconds; ++net.log_lines; } }
LogTime::LogTime() : start(uint64_t(std::chrono::duration_cast<std::chrono::nanoseconds>(Clock::now().time_since_epoch()).count())) { ++log_depth; }
LogTime::~LogTime() {
  const uint64_t now = uint64_t(std::chrono::duration_cast<std::chrono::nanoseconds>(Clock::now().time_since_epoch()).count());
  add_log_time(now - start, --log_depth == 0);
}

void stop_tracking() {
  mu_rollback::end();
  net_engine.end();
}
void shutdown() { if (net.on) netplay_bridge::shutdown(); net.on = false; }
} // namespace net_host
